// The showreel: a live, deterministic render of a system being built. render(t) is a
// pure function of time, so the page, the scrubber and the MP4 export share every frame.
import { DURATION, FPS, CHAPTERS, STAGES, T } from './timeline.js';
import { clamp, lerp, ease, prog, smoothstep, hash, TAU } from './util.js';
import { buildGraph, CARD, KINDS, stageAt } from './graph.js';
import { GLYPHS, rr, circle, polyline } from './glyphs.js';
import { drawTitles } from './titles.js';

export { DURATION, FPS, CHAPTERS };

const PAL = {
  bg: '#ffffff',
  ink: '#1d1d1f',
  ink2: '#424245',
  ink3: '#6e6e73',
  ink4: '#86868b',
  blue: '#0071e3',
};
const F = {
  display: '-apple-system, BlinkMacSystemFont, "SF Pro Display", "Geist", "Helvetica Neue", Arial, sans-serif',
  text: '-apple-system, BlinkMacSystemFont, "SF Pro Text", "Geist", "Helvetica Neue", Arial, sans-serif',
};
const FONT_FACES = ['400 20px Geist', '500 20px Geist', '600 20px Geist', '700 20px Geist'];
const rgba = ([r, g, b], a) => `rgba(${r},${g},${b},${a})`;

// ── Sprites ─────────────────────────────────────────────────────────────────
const SHADOW_PAD = 44;
const makeShadow = () => {
  const k = 1.5;
  const c = document.createElement('canvas');
  c.width = Math.ceil((CARD.w + SHADOW_PAD * 2) * k);
  c.height = Math.ceil((CARD.h + SHADOW_PAD * 2) * k);
  const g = c.getContext('2d');
  g.scale(k, k);
  g.fillStyle = '#fff';
  [[26, 10, 0.075], [5, 1.5, 0.05]].forEach(([blur, dy, a]) => {
    g.shadowColor = `rgba(0,0,0,${a})`;
    g.shadowBlur = blur * k;
    g.shadowOffsetY = dy * k;
    rr(g, SHADOW_PAD, SHADOW_PAD, CARD.w, CARD.h, CARD.r);
    g.fill();
  });
  return c;
};

const ICON = 40;
const makeIcon = (rgb, glyph) => {
  const k = 4;
  const c = document.createElement('canvas');
  c.width = c.height = ICON * k;
  const g = c.getContext('2d');
  g.scale(k, k);
  const grad = g.createLinearGradient(0, 0, 0, ICON);
  grad.addColorStop(0, rgba(rgb.map((v) => Math.min(255, v + 34)), 1));
  grad.addColorStop(1, rgba(rgb, 1));
  rr(g, 0, 0, ICON, ICON, 11);
  g.fillStyle = grad;
  g.fill();
  g.translate(ICON / 2, ICON / 2);
  g.scale(1.02, 1.02);
  g.strokeStyle = '#fff';
  g.fillStyle = '#fff';
  g.lineWidth = 2;
  g.lineCap = 'round';
  g.lineJoin = 'round';
  GLYPHS[glyph](g);
  return c;
};

const makePacket = (rgb) => {
  const c = document.createElement('canvas');
  c.width = 48;
  c.height = 20;
  const g = c.getContext('2d');
  const halo = g.createRadialGradient(24, 10, 0, 24, 10, 10);
  halo.addColorStop(0, rgba(rgb, 0.28));
  halo.addColorStop(1, rgba(rgb, 0));
  g.fillStyle = halo;
  g.fillRect(0, 0, 48, 20);
  const body = g.createLinearGradient(8, 0, 40, 0);
  body.addColorStop(0, rgba(rgb, 0));
  body.addColorStop(0.55, rgba(rgb, 0.85));
  body.addColorStop(1, rgba(rgb, 1));
  rr(g, 8, 7, 32, 6, 3);
  g.fillStyle = body;
  g.fill();
  return c;
};

// ── Edge geometry ───────────────────────────────────────────────────────────
const SEG = 22;
const bez = (p0, c0, c1, p1, u) => {
  const m = 1 - u;
  const a = m * m * m;
  const b = 3 * m * m * u;
  const c = 3 * m * u * u;
  const d = u * u * u;
  return [a * p0[0] + b * c0[0] + c * c1[0] + d * p1[0], a * p0[1] + b * c0[1] + c * c1[1] + d * p1[1]];
};

const edgeCurve = (a, b, style, portrait, toBox, blocked = () => true) => {
  const hw = CARD.w / 2;
  const hh = CARD.h / 2;
  if (toBox) {
    // Nearest point on the target box; leave the card from the facing side.
    const [x0, y0, x1, y1] = b;
    const px = clamp(a.x, x0, x1);
    const py = clamp(a.y, y0, y1);
    const vertical = Math.abs(a.y - py) > Math.abs(a.x - px);
    const sx = Math.sign(px - a.x) || 1;
    const sy = Math.sign(py - a.y) || 1;
    const p0 = vertical ? [a.x, a.y + sy * hh] : [a.x + sx * hw, a.y];
    const p1 = [px, py];
    const k = Math.max(40, (vertical ? Math.abs(p1[1] - p0[1]) : Math.abs(p1[0] - p0[0])) * 0.5);
    return vertical ? [p0, [p0[0], p0[1] + sy * k], [p1[0], p1[1] - sy * k], p1] : [p0, [p0[0] + sx * k, p0[1]], [p1[0] - sx * k, p1[1]], p1];
  }
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const sameRow = Math.abs(dy) < CARD.h * 0.9;
  const sameCol = Math.abs(dx) < CARD.w * 0.8;
  // Links that would cut through neighbours arc around them instead.
  if (sameRow && Math.abs(dx) > CARD.w * 1.6 && blocked(a, b, true)) {
    const k = 34 + Math.abs(dx) * 0.06;
    return [[a.x, a.y + hh], [a.x, a.y + hh + k], [b.x, b.y + hh + k], [b.x, b.y + hh]];
  }
  if (sameCol && Math.abs(dy) > CARD.h * 2.2 && blocked(a, b, false)) {
    const k = 40 + Math.abs(dy) * 0.08;
    return [[a.x + hw, a.y], [a.x + hw + k, a.y], [b.x + hw + k, b.y], [b.x + hw, b.y]];
  }
  let horizontal;
  if (style === 'telemetry' || style === 'logs') horizontal = Math.abs(dy) < Math.abs(dx) * 0.6;
  else if (sameRow) horizontal = true;
  else if (sameCol) horizontal = false;
  else horizontal = !portrait;
  if (horizontal) {
    const s = Math.sign(dx) || 1;
    const p0 = [a.x + s * hw, a.y];
    const p1 = [b.x - s * hw, b.y];
    const k = Math.max(36, Math.abs(p1[0] - p0[0]) * 0.5);
    return [p0, [p0[0] + s * k, p0[1]], [p1[0] - s * k, p1[1]], p1];
  }
  const s = Math.sign(dy) || 1;
  const p0 = [a.x, a.y + s * hh];
  const p1 = [b.x, b.y - s * hh];
  const k = Math.max(24, Math.abs(p1[1] - p0[1]) * 0.5);
  return [p0, [p0[0], p0[1] + s * k], [p1[0], p1[1] - s * k], p1];
};

const EDGE_STYLE = {
  flow: { width: 1.5, dash: null, color: 'rgba(60,60,67,0.2)', speed: 250, gap: 170, size: 1 },
  telemetry: { width: 1, dash: [2, 4], color: 'rgba(255,45,85,0.28)', speed: 170, gap: 200, size: 0.55, rgb: KINDS.observe },
  logs: { width: 1, dash: [2, 4], color: 'rgba(255,45,85,0.28)', speed: 170, gap: 200, size: 0.55, rgb: KINDS.observe },
  replica: { width: 1.3, dash: [5, 4], color: 'rgba(255,149,0,0.5)', speed: 210, gap: 150, size: 0.8, rgb: KINDS.db },
  dev: { width: 1.2, dash: [4, 4], color: 'rgba(72,72,74,0.16)', speed: 170, gap: 260, size: 0.62, rgb: [142, 142, 147] },
  deploy: { width: 1.5, dash: [6, 4], color: 'rgba(0,113,227,0.45)', speed: 230, gap: 170, size: 0.9, rgb: [0, 113, 227] },
};

export const loadFonts = () => Promise.all(FONT_FACES.map((f) => document.fonts.load(f, 'AaİŞĞ·—0'))).catch(() => {});

export const createReel = async (canvas, { format = 'auto', titles = true, safe = null } = {}) => {
  await loadFonts();
  const ctx = canvas.getContext('2d', { alpha: false });
  const shadow = makeShadow();
  const icons = new Map();
  const iconFor = (kind, glyph) => {
    const key = `${kind}:${glyph}`;
    if (!icons.has(key)) icons.set(key, makeIcon(KINDS[kind], glyph));
    return icons.get(key);
  };
  const packets = new Map();
  const packetFor = (rgb) => {
    const key = rgb.join(',');
    if (!packets.has(key)) packets.set(key, makePacket(rgb));
    return packets.get(key);
  };
  const graphs = {};
  const graphFor = (f) => (graphs[f] ||= buildGraph(f));
  let ambient = 0;
  let showTitles = titles;
  let safeOverride = safe;
  let camCache = null;

  const pickFormat = () => (format !== 'auto' ? format : canvas.height > canvas.width * 1.05 ? 'portrait' : 'landscape');

  const resize = (width, height) => {
    canvas.width = width;
    canvas.height = height;
    camCache = null;
  };
  if (!canvas.width) resize(1920, 1080);

  // Safe frame the graph is fitted into, as fractions of the canvas.
  const safeFrame = (portrait) => {
    if (safeOverride) return safeOverride;
    if (showTitles) return portrait ? { top: 0.1, bottom: 0.12, left: 0.05, right: 0.05 } : { top: 0.13, bottom: 0.15, left: 0.04, right: 0.04 };
    return portrait ? { top: 0.09, bottom: 0.28, left: 0.04, right: 0.04 } : { top: 0.11, bottom: 0.22, left: 0.03, right: 0.03 };
  };

  const DRIFT = 0.018;
  const cameraKeys = (G, cw, ch) => {
    const s = safeFrame(G.format === 'portrait');
    const key = `${G.format}:${cw}x${ch}:${s.top},${s.bottom},${s.left},${s.right}`;
    if (camCache?.key === key) return camCache.keys;
    const fx0 = cw * s.left;
    const fx1 = cw * (1 - s.right);
    const fy0 = ch * s.top;
    const fy1 = ch * (1 - s.bottom);
    const pad = 60;
    let prev = null;
    const keys = G.framings.map((f) => {
      const [x0, y0, x1, y1] = f.box;
      let z = Math.min((fx1 - fx0) / (x1 - x0 + pad * 2), (fy1 - fy0) / (y1 - y0 + pad * 2));
      if (prev) z = Math.min(z, prev.z * Math.exp(-DRIFT * (f.at - prev.at)));
      const k = { at: f.at, dur: f.dur, z, cx: (x0 + x1) / 2, cy: (y0 + y1) / 2 };
      prev = k;
      return k;
    });
    camCache = { key, keys, fx: (fx0 + fx1) / 2, fy: (fy0 + fy1) / 2 };
    return keys;
  };

  const camera = (G, t, cw, ch) => {
    const keys = cameraKeys(G, cw, ch);
    let i = 0;
    while (i + 1 < keys.length && t >= keys[i + 1].at) i++;
    const cur = keys[i];
    const drifted = (k) => k.z * Math.exp(-DRIFT * Math.max(0, t - k.at));
    let z = drifted(cur);
    let cx = cur.cx;
    let cy = cur.cy;
    if (i > 0) {
      const from = keys[i - 1];
      const u = ease.inOutCubic(prog(t, cur.at, cur.at + cur.dur));
      z = Math.exp(lerp(Math.log(drifted(from)), Math.log(z), u));
      cx = lerp(from.cx, cur.cx, u);
      cy = lerp(from.cy, cur.cy, u);
    } else {
      // Open slightly closer, then settle.
      z *= 1 + 0.1 * (1 - ease.outCubic(prog(t, 0, 1.6)));
    }
    if (showTitles) z *= 1 - 0.06 * ease.inOutCubic(prog(t, T.endcard - 0.4, T.endcard + 1.6));
    cx += 10 * Math.sin(t * 0.23);
    cy += 7 * Math.cos(t * 0.19);
    return { z, cx, cy, fx: camCache.fx, fy: camCache.fy };
  };

  // ── Layers ────────────────────────────────────────────────────────────────
  const drawGrid = (cam, cw, ch, alpha) => {
    const levels = [40, 160];
    levels.forEach((step, li) => {
      const px = step * cam.z;
      const a = alpha * (li === 0 ? smoothstep(10, 22, px) : smoothstep(8, 16, px) * (1 - smoothstep(60, 110, px)));
      if (a <= 0.01) return;
      ctx.fillStyle = `rgba(0,0,0,${(li === 0 ? 0.07 : 0.09) * a})`;
      const x0 = Math.floor((cam.cx - cam.fx / cam.z) / step) * step;
      const y0 = Math.floor((cam.cy - cam.fy / cam.z) / step) * step;
      const r = li === 0 ? 1 : 1.3;
      for (let wx = x0; wx < cam.cx + (cw - cam.fx) / cam.z + step; wx += step) {
        const sx = (wx - cam.cx) * cam.z + cam.fx;
        for (let wy = y0; wy < cam.cy + (ch - cam.fy) / cam.z + step; wy += step) {
          const sy = (wy - cam.cy) * cam.z + cam.fy;
          ctx.fillRect(sx - r, sy - r, r * 2, r * 2);
        }
      }
    });
  };

  const label = (g, s, glyph, rgb, z, dim, isRegion) => {
    const px = 15 * z;
    if (px < 5) return;
    const a = s.a * dim * smoothstep(5, 9, px);
    const x = s.x0 + 18;
    const y = s.y0 + 26;
    ctx.save();
    ctx.globalAlpha = a;
    ctx.translate(x + 8, y - 5);
    ctx.scale(0.62, 0.62);
    ctx.strokeStyle = rgba(rgb, 1);
    ctx.fillStyle = rgba(rgb, 1);
    ctx.lineWidth = 2.2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    GLYPHS[glyph](ctx);
    ctx.restore();
    ctx.font = `600 15px ${F.text}`;
    ctx.fillStyle = rgba(rgb, 1);
    ctx.textAlign = 'left';
    ctx.globalAlpha = a;
    ctx.fillText(g.label, x + 24, y);
    if (isRegion && s.regionLabel > 0) {
      const w = ctx.measureText(g.label).width;
      ctx.globalAlpha = a * s.regionLabel;
      ctx.fillStyle = PAL.ink4;
      ctx.font = `500 15px ${F.text}`;
      ctx.fillText(`· ${g.regionLabel}`, x + 30 + w, y);
    }
    ctx.globalAlpha = 1;
  };

  const drawGroups = (G, t, z, dim) => {
    const states = G.groups.map((g) => [g, G.groupState(g, t)]).filter(([, s]) => s);
    // AWS regions: a whisper of fill and a hairline.
    states.forEach(([g, s]) => {
      if (g.type !== 'aws') return;
      ctx.globalAlpha = s.a * dim;
      rr(ctx, s.x0, s.y0, s.x1 - s.x0, s.y1 - s.y0, 34);
      ctx.fillStyle = 'rgba(0,0,0,0.018)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.07)';
      ctx.lineWidth = 1 / z;
      ctx.stroke();
      label(g, s, 'cloud', [99, 99, 102], z, dim, true);
    });
    states.forEach(([g, s]) => {
      if (g.type !== 'k8s') return;
      ctx.globalAlpha = s.a * dim;
      rr(ctx, s.x0, s.y0, s.x1 - s.x0, s.y1 - s.y0, 26);
      ctx.setLineDash([6 / z, 5 / z]);
      ctx.strokeStyle = 'rgba(88,86,214,0.38)';
      ctx.lineWidth = 1.2 / z;
      ctx.stroke();
      ctx.setLineDash([]);
      label(g, s, 'helm', KINDS.service, z, dim, false);
    });
    ctx.globalAlpha = 1;
  };

  const endpoint = (G, id, t) => {
    const n = G.node(id);
    if (n) return { n, s: G.nodeState(n, t) };
    const g = G.group(id);
    return { g, s: g && G.groupState(g, t) };
  };

  const drawEdges = (G, t, z, dim, packetAlpha) => {
    const portrait = G.format === 'portrait';
    const curves = [];
    const live = [];
    G.nodes.forEach((n) => {
      const s = G.nodeState(n, t);
      if (s) live.push(s);
    });
    // Does any other card sit on the straight line between a and b?
    const blocked = (a, b, horizontal) =>
      live.some((s) => {
        if (s === a || s === b) return false;
        if (horizontal) return Math.abs(s.y - a.y) < CARD.h && s.x > Math.min(a.x, b.x) + 20 && s.x < Math.max(a.x, b.x) - 20;
        return Math.abs(s.x - a.x) < CARD.w * 0.8 && s.y > Math.min(a.y, b.y) + 20 && s.y < Math.max(a.y, b.y) - 20;
      });
    G.edges.forEach((e) => {
      const st = G.edgeState(e, t);
      if (!st) return;
      const A = endpoint(G, e.from, t);
      const B = endpoint(G, e.to, t);
      if (!A.s || !B.s) return;
      const toBox = !!B.g;
      const pts = edgeCurve(A.s, toBox ? [B.s.x0, B.s.y0, B.s.x1, B.s.y1] : B.s, e.style, portrait, toBox, blocked);
      const a = st.a * Math.min(A.s.a, B.s.a) * dim;
      if (a <= 0.01) return;
      curves.push({ e, st, pts, a, src: A.n });
    });
    // Lines.
    const quiet = 1 - 0.45 * prog(t, T.split, T.split + 1.2);
    curves.forEach(({ e, st, pts, a }) => {
      const S = EDGE_STYLE[e.style];
      ctx.globalAlpha = a * (e.style === 'telemetry' || e.style === 'logs' ? quiet : 1);
      ctx.strokeStyle = S.color;
      ctx.lineWidth = S.width / z;
      ctx.setLineDash(S.dash ? S.dash.map((d) => d / z) : []);
      ctx.beginPath();
      const n = Math.max(2, Math.ceil(SEG * st.draw));
      for (let k = 0; k <= n; k++) {
        const [x, y] = bez(...pts, (k / n) * st.draw);
        k ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      }
      ctx.stroke();
      if (st.draw < 1) {
        // A bright head leads the line as it draws in.
        const [hx, hy] = bez(...pts, st.draw);
        ctx.setLineDash([]);
        ctx.globalAlpha = a * (1 - st.draw) * 0.9;
        circle(ctx, hx, hy, 3.2 / z + 1.5);
        ctx.fillStyle = PAL.blue;
        ctx.fill();
      }
    });
    ctx.setLineDash([]);
    // Traffic.
    curves.forEach(({ e, st, pts, a, src }) => {
      if (st.flow <= 0) return;
      const S = EDGE_STYLE[e.style];
      const rgb = S.rgb || KINDS[src?.kind] || KINDS.service;
      const sprite = packetFor(rgb);
      let len = 0;
      let prev = pts[0];
      for (let k = 1; k <= 8; k++) {
        const p = bez(...pts, k / 8);
        len += Math.hypot(p[0] - prev[0], p[1] - prev[1]);
        prev = p;
      }
      const count = Math.max(1, Math.round(len / S.gap));
      const scale = Math.max(S.size, (S.size * 0.9) / z);
      const w = 24 * scale;
      const h = 10 * scale;
      for (let i = 0; i < count; i++) {
        const u = (t * S.speed) / len + hash(e.i, i) + i / count;
        const f = u - Math.floor(u);
        const edgeFade = smoothstep(0, 0.06, f) * (1 - smoothstep(0.92, 1, f));
        const pa = a * st.flow * edgeFade * packetAlpha * (e.style === 'telemetry' || e.style === 'logs' ? 0.4 + 0.6 * quiet : 1);
        if (pa <= 0.02) continue;
        const [x, y] = bez(...pts, f);
        const [x2, y2] = bez(...pts, Math.min(1, f + 0.01));
        const ang = Math.atan2(y2 - y, x2 - x);
        ctx.globalAlpha = pa;
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(ang);
        ctx.drawImage(sprite, -w * 0.83, -h / 2, w, h);
        ctx.restore();
      }
    });
    ctx.globalAlpha = 1;
  };

  const wave = (G, t) => {
    if (t < T.rollout[0] || t > T.rollout[1] + 0.8) return null;
    const p = ease.inOutSine(prog(t, T.rollout[0], T.rollout[1]));
    return { pos: lerp(G.sweep[0], G.sweep[1], p), dir: Math.sign(G.sweep[0] - G.sweep[1]) || 1, fade: 1 - prog(t, T.rollout[1], T.rollout[1] + 0.8) };
  };

  const drawNodes = (G, t, z, dim) => {
    const px = CARD.h * z;
    const textA = smoothstep(13, 22, px);
    const subA = smoothstep(22, 32, px);
    const portrait = G.format === 'portrait';
    const W = wave(G, t);
    const list = [];
    G.nodes.forEach((n) => {
      const s = G.nodeState(n, t);
      if (s) list.push([n, s]);
    });
    // Entry pulses behind the cards.
    list.forEach(([n, s]) => {
      if (s.pulse <= 0 || s.pulse >= 1) return;
      const g = 4 + 20 * ease.outCubic(s.pulse);
      ctx.globalAlpha = 0.22 * (1 - s.pulse) ** 2 * dim;
      rr(ctx, s.x - CARD.w / 2 - g, s.y - CARD.h / 2 - g, CARD.w + g * 2, CARD.h + g * 2, CARD.r + g);
      ctx.strokeStyle = rgba(KINDS[n.kind], 1);
      ctx.lineWidth = 1.5 / z;
      ctx.stroke();
    });
    list.forEach(([n, s]) => {
      const a = s.a * dim;
      const w = CARD.w * s.s;
      const h = CARD.h * s.s;
      const x = s.x - w / 2;
      const y = s.y - h / 2;
      if (s.stack > 0) {
        for (let k = 2; k >= 1; k--) {
          const o = 7 * k * s.stack;
          ctx.globalAlpha = a * s.stack * (k === 2 ? 0.75 : 0.95);
          rr(ctx, x + o, y - o, w, h, CARD.r);
          ctx.fillStyle = k === 2 ? '#f5f5f7' : '#fafafc';
          ctx.fill();
          ctx.strokeStyle = 'rgba(0,0,0,0.07)';
          ctx.lineWidth = 1 / z;
          ctx.stroke();
        }
      }
      ctx.globalAlpha = a;
      ctx.drawImage(shadow, x - SHADOW_PAD * s.s, y - SHADOW_PAD * s.s, (CARD.w + SHADOW_PAD * 2) * s.s, (CARD.h + SHADOW_PAD * 2) * s.s);
      rr(ctx, x, y, w, h, CARD.r);
      ctx.fillStyle = '#fff';
      ctx.fill();
      let hi = 0;
      let done = 0;
      if (W) {
        const d = s.y - W.pos;
        hi = Math.exp(-((d / 120) ** 2)) * W.fade;
        done = clamp((d * W.dir) / 80) * W.fade;
      }
      ctx.strokeStyle = hi > 0.02 ? `rgba(0,113,227,${0.1 + 0.8 * hi})` : 'rgba(0,0,0,0.085)';
      ctx.lineWidth = (1 + 1.4 * hi) / z;
      ctx.stroke();
      ctx.drawImage(iconFor(n.kind, n.glyph), x + 13 * s.s, s.y - (ICON / 2) * s.s, ICON * s.s, ICON * s.s);
      if (textA > 0) {
        const tx = x + 66 * s.s;
        ctx.textAlign = 'left';
        ctx.globalAlpha = a * textA;
        ctx.font = `600 ${17 * s.s}px ${F.text}`;
        ctx.fillStyle = PAL.ink;
        ctx.fillText(n.label, tx, s.y + lerp(6, -2.5, subA) * s.s);
        if (subA > 0) {
          ctx.globalAlpha = a * subA;
          ctx.font = `400 ${13.5 * s.s}px ${F.text}`;
          ctx.fillStyle = PAL.ink4;
          ctx.fillText(n.sub, tx, s.y + 16 * s.s);
        }
      }
      if (s.status > 0) {
        ctx.globalAlpha = a * s.status * (1 - done);
        circle(ctx, x + w - 15, y + 15, 3.6);
        ctx.fillStyle = '#34c759';
        ctx.fill();
      }
      if (done > 0.01) {
        // Deployed: a small blue check replaces the status light.
        ctx.globalAlpha = a * done;
        circle(ctx, x + w - 15, y + 15, 7);
        ctx.fillStyle = PAL.blue;
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.8;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        polyline(ctx, [[x + w - 18.2, y + 15.2], [x + w - 15.8, y + 17.6], [x + w - 11.6, y + 12.6]]);
        ctx.stroke();
      }
    });
    ctx.globalAlpha = 1;
  };

  const drawWave = (G, t, dim) => {
    const W = wave(G, t);
    if (!W) return;
    const [x0, y0, x1, y1] = G.full;
    const half = 180;
    const grad = ctx.createLinearGradient(0, W.pos - half, 0, W.pos + half);
    grad.addColorStop(0, 'rgba(0,113,227,0)');
    grad.addColorStop(0.5, `rgba(0,113,227,${0.07 * W.fade * dim})`);
    grad.addColorStop(1, 'rgba(0,113,227,0)');
    ctx.fillStyle = grad;
    ctx.fillRect(x0 - 400, W.pos - half, x1 - x0 + 800, half * 2);
  };

  const render = (time) => {
    const t = clamp(time, 0, DURATION - 1e-4);
    const cw = canvas.width;
    const ch = canvas.height;
    const G = graphFor(pickFormat());
    const portrait = G.format === 'portrait';
    const cam = camera(G, t, cw, ch);

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
    ctx.fillStyle = PAL.bg;
    ctx.fillRect(0, 0, cw, ch);

    const endDim = showTitles ? 1 - 0.86 * ease.inOutCubic(prog(t, T.endcard - 0.3, T.endcard + 0.5)) : 1;
    const dim = endDim * (1 - 0.15 * ambient);
    drawGrid(cam, cw, ch, dim * prog(t, 0, 0.6));

    ctx.setTransform(cam.z, 0, 0, cam.z, cam.fx - cam.cx * cam.z, cam.fy - cam.cy * cam.z);
    drawGroups(G, t, cam.z, dim);
    drawWave(G, t, dim);
    drawEdges(G, t, cam.z, dim, 1 - 0.35 * ambient);
    drawNodes(G, t, cam.z, dim);

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    if (showTitles) drawTitles(ctx, t, cw, ch, portrait);

    // Fade in from white, and back to white for a seamless loop.
    const fade = Math.max(1 - prog(t, 0, 0.35), ease.inQuad(prog(t, T.fadeOut, DURATION)));
    if (fade > 0) {
      ctx.globalAlpha = fade;
      ctx.fillStyle = PAL.bg;
      ctx.fillRect(0, 0, cw, ch);
      ctx.globalAlpha = 1;
    }
  };

  return {
    render,
    resize,
    // 0 = the film, 1 = a calm backdrop behind page content.
    setAmbient: (x) => (ambient = clamp(x)),
    setTitles: (on) => {
      showTitles = on;
      camCache = null;
    },
    setSafe: (s) => {
      safeOverride = s;
      camCache = null;
    },
    get format() {
      return pickFormat();
    },
    duration: DURATION,
    fps: FPS,
    chapters: CHAPTERS,
  };
};
